function createOnce(work) {
  const jobs = new Map();
  return function run(id) {
    if (jobs.has(id)) return jobs.get(id);
    const promise = Promise.resolve().then(() => work(id)).catch(error => {
      jobs.delete(id);
      throw error;
    });
    jobs.set(id, promise);
    return promise;
  };
}

